def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my_last, opp_last = history[-1]
    if n == 1:
        return 'C' if opp_last == 'C' else 'D'

    opp_c = 0
    my_d = 0
    for m, o in history:
        if o == 'C':
            opp_c += 1
        if m == 'D':
            my_d += 1
    opp_d = n - opp_c
    my_c = n - my_d
    opp_coop_rate = opp_c / n
    opp_def_rate = opp_d / n

    i = n - 1
    opp_d_streak = 0
    while i >= 0 and history[i][1] == 'D':
        opp_d_streak += 1
        i -= 1

    i = n - 1
    opp_c_streak = 0
    while i >= 0 and history[i][1] == 'C':
        opp_c_streak += 1
        i -= 1

    i = n - 1
    my_d_streak = 0
    while i >= 0 and history[i][0] == 'D':
        my_d_streak += 1
        i -= 1

    i = n - 1
    my_c_streak = 0
    while i >= 0 and history[i][0] == 'C':
        my_c_streak += 1
        i -= 1

    dc_c = 0
    dc_d = 0
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i][1] == 'C':
            if history[i + 1][1] == 'C':
                dc_c += 1
            else:
                dc_d += 1
    dc_total = dc_c + dc_d

    defector = (
        opp_d_streak >= 4 or
        opp_def_rate >= 0.62 or
        (opp_d >= 18 and opp_d > opp_c)
    )
    retaliatory = (
        dc_total > 0 and
        dc_d > dc_c and
        opp_def_rate < 0.35
    )

    if n >= 99:
        return 'D'
    if defector:
        return 'D'

    if (
        my_last == 'D' and
        opp_last == 'C' and
        dc_total == 0 and
        opp_coop_rate >= 0.40 and
        opp_def_rate < 0.38
    ):
        return 'C'

    if opp_last == 'C':
        if dc_c > dc_d:
            return 'D'

        if dc_c == dc_d and dc_c > 0:
            if opp_def_rate < 0.35:
                return 'D' if rng.random() < 0.28 else 'C'
            return 'D' if rng.random() < 0.58 else 'C'

        if dc_d > dc_c and dc_c == 0 and retaliatory:
            return 'C'

        if opp_def_rate >= 0.38 and not retaliatory:
            return 'D'

        if (
            opp_c_streak >= 6 and
            opp_coop_rate >= 0.65 and
            n <= 88 and
            dc_total == 0
        ):
            return 'D'

        return 'C'

    if opp_def_rate >= 0.38 and not retaliatory:
        if my_c_streak >= 2 or opp_d_streak >= 2:
            return 'D'

    if my_last == 'D':
        if opp_def_rate >= 0.40 and not retaliatory and opp_d_streak <= 4:
            return 'D'
        if opp_coop_rate > 0.35 and opp_d_streak <= 3:
            return 'C'
        return 'D'

    if my_c_streak >= 3 and opp_d_streak >= 3:
        return 'D'

    if opp_d > opp_c:
        return 'D'

    if opp_coop_rate > 0.60 and opp_d_streak <= 3:
        return 'C'

    if opp_def_rate >= 0.45:
        return 'D'

    return 'C'
